    pub fn apply(&mut self, event: &Event) -> Result<bool, String> {
        Self::validate(event)?;

        if let Some(existing) = self.requests.get(event.id()) {
            return if existing == event {
                Ok(false)
            } else {
                Err("重复的请求编号内容不一致".to_owned())
            };
        }

        // Compute first, commit last: any error below leaves state untouched.
        match event {
            Event::Deposit { id, account, cents } => {
                let current = self.balances.get(account).copied().unwrap_or(0);
                let updated = current
                    .checked_add(*cents)
                    .ok_or_else(|| "余额溢出".to_owned())?;
                self.balances.insert(account.clone(), updated);
                self.requests.insert(id.clone(), event.clone());
            }
            Event::Transfer { id, from, to, cents } => {
                let source = *self
                    .balances
                    .get(from)
                    .ok_or_else(|| "源账户不存在".to_owned())?;
                let target = *self
                    .balances
                    .get(to)
                    .ok_or_else(|| "目标账户不存在".to_owned())?;
                if source < *cents {
