use amount::format_cents;
use csv::parse_events;
use ledger::Ledger;

/// Build the account report from the raw ledger input.
///
/// Parsing errors and apply errors are both propagated; a successful replay
/// (`Ok(false)`) leaves the report unchanged. The output is the user header,
/// one `account,balance` line per account sorted by account name, and a final
/// newline.
pub fn run(input: &str) -> Result<String, String> {
    let mut ledger = Ledger::new();
    for event in parse_events(input)? {
        ledger.apply(&event)?;
    }

    let mut output = format!("{}\n", user_policy::REPORT_HEADER);
    for (account, cents) in ledger.balances() {
        output.push_str(&format!("{},{}\n", account, format_cents(*cents)));
    }
    Ok(output)
}

